class Solution:
    def interactionCost(self, n: int, edges: list[list[int]], group: list[int]) -> int:
        adj = [[] for _ in range(n)]
        for u, v in edges:
            adj[u].append(v); adj[v].append(u)
        total = [0] * 21
        for g in group: total[g] += 1
        parent = [-1] * n
        order = [0]
        parent[0] = -2
        for u in order:
            for w in adj[u]:
                if parent[w] == -1:
                    parent[w] = u
                    order.append(w)
        cnt = [[0] * 21 for _ in range(n)]
        ans = 0
        for u in reversed(order):
            cnt[u][group[u]] += 1
            p = parent[u]
            if p >= 0:
                cu = cnt[u]
                for g in range(1, 21):
                    if cu[g]:
                        ans += cu[g] * (total[g] - cu[g])
                        cnt[p][g] += cu[g]
        return ans

