class Solution {
public:
    long long interactionCost(int n, vector<vector<int>>& edges, vector<int>& group) {
        vector<vector<int>> adj(n);
        for (auto& e : edges) { adj[e[0]].push_back(e[1]); adj[e[1]].push_back(e[0]); }
        long long total[21] = {};
        for (int g : group) total[g]++;
        vector<int> parent(n, -1), order;
        order.reserve(n);
        parent[0] = -2; order.push_back(0);
        for (size_t i = 0; i < order.size(); i++)
            for (int w : adj[order[i]])
                if (parent[w] == -1) { parent[w] = order[i]; order.push_back(w); }
        vector<array<long long,21>> cnt(n);
        for (auto& a : cnt) a.fill(0);
        long long ans = 0;
        for (int i = n - 1; i >= 0; i--) {
            int u = order[i];
            cnt[u][group[u]]++;
            int p = parent[u];
            if (p >= 0) {
                for (int g = 1; g <= 20; g++) if (cnt[u][g]) {
                    ans += cnt[u][g] * (total[g] - cnt[u][g]);
                    cnt[p][g] += cnt[u][g];
                }
            }
        }
        return ans;
    }
};

