class Solution {
    public long interactionCost(int n, int[][] edges, int[] group) {
        List<List<Integer>> adj = new ArrayList<>();
        for (int i = 0; i < n; i++) adj.add(new ArrayList<>());
        for (int[] e : edges) { adj.get(e[0]).add(e[1]); adj.get(e[1]).add(e[0]); }
        long[] total = new long[21];
        for (int g : group) total[g]++;
        int[] parent = new int[n];
        java.util.Arrays.fill(parent, -1);
        List<Integer> order = new ArrayList<>();
        parent[0] = -2; order.add(0);
        for (int i = 0; i < order.size(); i++)
            for (int w : adj.get(order.get(i)))
                if (parent[w] == -1) { parent[w] = order.get(i); order.add(w); }
        long[][] cnt = new long[n][21];
        long ans = 0;
        for (int i = n - 1; i >= 0; i--) {
            int u = order.get(i);
            cnt[u][group[u]]++;
            int p = parent[u];
            if (p >= 0) {
                for (int g = 1; g <= 20; g++) if (cnt[u][g] > 0) {
                    ans += cnt[u][g] * (total[g] - cnt[u][g]);
                    cnt[p][g] += cnt[u][g];
                }
            }
        }
        return ans;
    }
}

